/**
 * Which drawing stands in for an animal with no photograph. A port of the web
 * app's frontend/src/lib/silhouettes.ts (upande_livestock), so an animal wears
 * the same picture on the phone and on the desk.
 *
 * Two steps. First the CLASS, from species, then age, then sex and stage.
 * Then the POSE within that class, chosen from the animal's own number, so a
 * list of photo-less animals is not one picture repeated, and the same animal
 * always gets the same picture.
 *
 * The drawings are in src/art/paths.ts (generated by scripts/build-art.mjs
 * from the backend's design/silhouettes/).
 */

export type SilhouetteClass =
  "cow" | "heifer" | "bull" | "steer" | "calf" | "sheep" | "goat" | "goat-kid";

export type Silhouette =
  | "cow" | "cow-udder" | "cow-grazing" | "cow-grazing-2"
  | "heifer"
  | "bull"
  | "steer" | "steer-turned" | "steer-grazing"
  | "calf" | "calf-grazing"
  | "sheep"
  | "goat" | "goat-kid";

/** The poses of each class (the first is the plain standing one). Sheep and
 *  goats have one drawing each: the sheep, the horned adult goat and the kid. */
export const POSES: Record<SilhouetteClass, readonly Silhouette[]> = {
  cow: ["cow", "cow-udder", "cow-grazing-2", "cow-grazing"],
  heifer: ["heifer", "cow-grazing"],
  bull: ["bull"],
  steer: ["steer", "steer-turned", "steer-grazing"],
  calf: ["calf", "calf-grazing"],
  sheep: ["sheep"],
  goat: ["goat"],
  "goat-kid": ["goat-kid"],
};

/** What the pick reads. Every field but the number may be missing. The phone
 *  writes sex as "M"/"F" and the web as "Male"/"Female"; both are read. */
export type SilhouetteSubject = {
  id: string;
  sex?: string | null;
  stage?: string | null;
  species?: string | null;
  dob?: string | null;
  /** The old reproductive status; "Calf" counts as the calf stage when no stage is known. */
  repro?: string | null;
};

/** Younger than this and it is drawn as a calf (a goat as a kid), whatever its stage says. */
export const CALF_DAYS = 210;
/** A female younger than this, whose stage does not say she has calved, is a heifer. */
export const HEIFER_DAYS = 730;

/** Stages that mean she has calved: a cow. */
const CALVED = ["fresh", "served", "confirmed"];

function ageDays(dob: string | null | undefined, now: Date): number | null {
  if (!dob) return null;
  const t = new Date(dob).getTime();
  if (Number.isNaN(t)) return null;
  return Math.max(0, Math.floor((now.getTime() - t) / 86400000));
}

function sexOf(sex: string | null | undefined): "Male" | "Female" | null {
  const s = String(sex ?? "").trim().toUpperCase();
  if (s === "M" || s === "MALE") return "Male";
  if (s === "F" || s === "FEMALE") return "Female";
  return null;
}

export function silhouetteClass(a: Omit<SilhouetteSubject, "id">, now = new Date()): SilhouetteClass {
  const species = (a.species || "").toLowerCase();
  const stage = a.stage || (a.repro === "Calf" ? "calf" : null);
  const age = ageDays(a.dob, now);
  const young = stage === "calf" || (age !== null && age < CALF_DAYS);
  if (species === "sheep") return "sheep";
  if (species === "goat" || species === "goats") return young ? "goat-kid" : "goat";

  if (young) return "calf";

  const sex = sexOf(a.sex);
  if (sex === "Male") return stage === "bull" ? "bull" : "steer";
  if (sex !== "Female") return "steer"; // sex not recorded: the feedlot's usual animal

  if (stage === "heifer") return "heifer";
  if (stage && CALVED.includes(stage)) return "cow";
  // "open" is what a list sends for every animal still on the farm, so age decides.
  return age !== null && age < HEIFER_DAYS ? "heifer" : "cow";
}

/** FNV-1a 32-bit over the trimmed, upper-cased number: the web app's hash. */
export function tagHash(id: string): number {
  let h = 0x811c9dc5;
  const s = (id || "").trim().toUpperCase();
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h >>> 0;
}

export function pickSilhouette(a: SilhouetteSubject, now = new Date()): Silhouette {
  const poses = POSES[silhouetteClass(a, now)];
  return poses[tagHash(a.id) % poses.length];
}
